contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint beforeBalance0 = c.getBalance(address(0)); if (__ESBMC_reverted()) return;
        uint beforeBalance1 = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint afterBalance0 = c.getBalance(address(0)); if (__ESBMC_reverted()) return;
        uint afterBalance1 = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        assert(afterBalance0 >= beforeBalance0 && afterBalance1 >= beforeBalance1);
    }

    receive() external payable {}
}

