// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBalance0;
        try c.getBalance(address(0)) returns (uint256 __r) { beforeBalance0 = __r; } catch { return; }
        uint256 beforeBalance1;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeBalance1 = __r; } catch { return; }
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 afterBalance0;
        try c.getBalance(address(0)) returns (uint256 __r) { afterBalance0 = __r; } catch { return; }
        uint256 afterBalance1;
        try c.getBalance(address(this)) returns (uint256 __r) { afterBalance1 = __r; } catch { return; }
        assertTrue(afterBalance0 >= beforeBalance0 && afterBalance1 >= beforeBalance1);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
